<?php extract($document,EXTR_SKIP);$e=static fn($value)=>authEscape($value);$number=static fn($value,$scale=2)=>number_format((float)$value,$scale,',','.');$currency=$row['currency_code']??'';$party=($kind==='purchase_orders'||($kind==='invoices'&&$row['invoice_type']==='supplier')||($stock&&$row['operation_type']==='receipt'))?'Proveedor':'Cliente'; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.' · '.$row['name']) ?></title><link rel="stylesheet" href="<?= $e(authBasePath()) ?>/css/document-print.css?v=<?= filemtime(dirname(__DIR__).'/css/document-print.css') ?>"><script src="<?= $e(authBasePath()) ?>/js/document-print.js" defer></script></head><body>
<nav class="print-toolbar" aria-label="Acciones del documento"><a href="<?= $e($source) ?>">← Volver a la ficha</a><span>Vista previa · A4</span><button type="button" data-print-document>Imprimir / Guardar PDF</button></nav>
<main class="document-paper <?= $stock?'document-stock':'document-commercial' ?>">
<header class="document-header"><div class="document-brand"><?php if(!empty($company['logo_data'])&&in_array($company['logo_mime'],['image/png','image/jpeg','image/webp'],true)): ?><img alt="Logo de <?= $e($company['name']) ?>" src="data:<?= $e($company['logo_mime']) ?>;base64,<?= base64_encode($company['logo_data']) ?>"><?php else: ?><span class="brand-mark" aria-hidden="true"><?= $e(mb_strtoupper(mb_substr($company['name'],0,1))) ?></span><?php endif; ?><div><h2><?= $e($company['legal_name']?:$company['name']) ?></h2><?php foreach(['tax_id','address','phone','email','website'] as $field): ?><?php if(!empty($company[$field])): ?><p><?= nl2br($e($company[$field])) ?></p><?php endif; ?><?php endforeach; ?></div></div><div class="document-heading"><p class="document-kicker"><?= $stock?'INVENTARIO':'DOCUMENTO COMERCIAL' ?></p><h1><?= $e($title) ?></h1><p class="document-reference"><?= $e($row['name']) ?></p><span class="document-status <?= $row['status']==='cancel'?'status-cancel':'' ?>"><?= $e($status) ?></span></div></header>
<section class="document-parties"><div class="document-partner"><h2><?= $stock&&$row['operation_type']==='internal'?'Movimiento entre ubicaciones':$party ?></h2><?php if($contact): ?><strong><?= $e($contact['name']) ?></strong><?php foreach(['tax_id','address','phone','email'] as $field): ?><?php if(!empty($contact[$field])): ?><p><?= nl2br($e($contact[$field])) ?></p><?php endif; ?><?php endforeach; ?><?php endif; ?><?php if(!empty($row['delivery_address'])&&$row['delivery_address']!==($contact['address']??'')): ?><h2>Dirección de entrega</h2><p><?= nl2br($e($row['delivery_address'])) ?></p><?php endif; ?></div><dl class="document-meta"><?php foreach(array_merge($meta,$references) as $label=>$value): ?><div><dt><?= $e($label) ?></dt><dd><?= $e(preg_match('/^\d{4}-\d{2}-\d{2}$/D',(string)$value)?implode('/',array_reverse(explode('-',$value))):$value) ?></dd></div><?php endforeach; ?></dl></section>
<?php if($row['status']==='draft'): ?><p class="document-draft">BORRADOR · Pendiente de confirmación</p><?php endif; ?>
<div class="document-lines-wrap"><table class="document-lines"><thead><tr><th class="line-index">#</th><th>Descripción</th><?php if($stock): ?><th class="numeric">Solicitado</th><th class="numeric"><?= $row['status']==='done'?'Realizado':'Por realizar' ?></th><?php else: ?><th class="numeric">Cantidad</th><th class="numeric">Precio unitario</th><th class="numeric">Impuesto</th><th class="numeric">Importe</th><?php endif; ?></tr></thead><tbody><?php foreach($lines as $index=>$line): ?><tr><td class="line-index"><?= $index+1 ?></td><td class="line-description"><?= $e($line['product_name']) ?></td><?php if($stock): ?><td class="numeric"><?= $number($line['demand'],3) ?></td><td class="numeric"><?= $number($line['quantity'],3) ?></td><?php else: ?><td class="numeric"><?= $number($line['quantity'],3) ?></td><td class="numeric"><?= $number($line['unit_price']) ?></td><td class="numeric"><?= $number($line['tax_rate']??0) ?> %</td><td class="numeric"><?= $number($line['total_amount']) ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$lines): ?><tr><td colspan="<?= $stock?4:6 ?>">Sin líneas registradas.</td></tr><?php endif; ?></tbody></table></div>
<section class="document-bottom"><div class="document-notes"><?php if(!empty($row['notes'])||!empty($row['credit_reason'])): ?><h2>Observaciones</h2><p><?= nl2br($e($row['notes']??$row['credit_reason'])) ?></p><?php endif; ?><?php if(!$stock&&!empty($row['exchange_rate'])): ?><p class="document-exchange">Tasa del documento: 1 <?= $e($row['currency_primary_code']) ?> = <?= $number($row['exchange_rate'],8) ?> <?= $e($row['currency_alternate_code']) ?></p><?php endif; ?></div><?php if(!$stock): ?><dl class="document-totals"><div><dt>Base imponible</dt><dd><?= $number($row['base_amount']) ?> <?= $e($currency) ?></dd></div><?php foreach($taxes as $tax): ?><div><dt><?= $e($tax['name']) ?></dt><dd><?= $number($tax['amount']) ?> <?= $e($currency) ?></dd></div><?php endforeach; ?><div class="document-grand-total"><dt>Total</dt><dd><?= $number($row['total_amount']) ?> <?= $e($currency) ?></dd></div></dl><?php endif; ?></section>
<?php if($stock): ?><section class="document-signatures"><div>Entregado por<span>Nombre, firma y fecha</span></div><div>Recibido por<span>Nombre, firma y fecha</span></div></section><?php endif; ?>
<footer class="document-footer"><span><?= $e($company['name']) ?> · <?= $e($row['name']) ?></span><span>Generado con Nexo</span></footer></main></body></html>
